#include <iostream>

template <typename Derived>
struct Drawable {
  void draw() {
    static_cast<Derived&>(*this).draw_impl();
  }
};

struct Circle : Drawable<Circle> {
  void draw_impl() { std::cout << 'C'; }
};
struct Square : Drawable<Square> {
  void draw_impl() { std::cout << 'S'; }
};

int main() {
  Circle circle;
  Square square;
  Drawable<Circle>& c = circle;
  Drawable<Square>& s = square;
  c.draw();
  s.draw();
}
